// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.estimate;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.sail.lmdb.estimate.LmdbPageCardinalityEstimator.IndexConfiguration;
import org.eclipse.rdf4j.sail.lmdb.estimate.LmdbPageCardinalityEstimator.IndexShape;
import org.junit.jupiter.api.Test;

class LmdbPageCardinalityEstimatorIndexLayoutTest {
	private static final long[] VALUES = { 11L, 22L, 33L, 44L };
	private static final List<String> INDEX_PERMUTATIONS = indexPermutations();

	@Test
	void describesEveryBindingShapeForEveryIndexPermutation() {
		for (String fieldSequence : INDEX_PERMUTATIONS) {
			IndexConfiguration configuration = LmdbPageCardinalityEstimator
					.createIndexConfiguration(List.of(fieldSequence));
			for (int bindingMask = 0; bindingMask < 16; bindingMask++) {
				IndexShape shape = configuration.indexShape(0, bindingMask);
				int expectedPrefixLength = expectedPrefixLength(fieldSequence, bindingMask);
				int expectedPrefixMask = expectedPrefixMask(fieldSequence, expectedPrefixLength);
				String message = fieldSequence + " binding mask " + Integer.toBinaryString(bindingMask);

				assertEquals(expectedPrefixLength, shape.prefixLength(), message);
				assertEquals(expectedPrefixMask, shape.prefixComponentMask(), message);
				assertEquals(Integer.bitCount(bindingMask) - expectedPrefixLength, shape.residualFieldCount(),
						message);
				assertEquals(expectedRangeValue(expectedPrefixMask, 0), shape.rangeSubject(VALUES[0]), message);
				assertEquals(expectedRangeValue(expectedPrefixMask, 1), shape.rangePredicate(VALUES[1]), message);
				assertEquals(expectedRangeValue(expectedPrefixMask, 2), shape.rangeObject(VALUES[2]), message);
				assertEquals(expectedRangeValue(expectedPrefixMask, 3), shape.rangeContext(VALUES[3]), message);
			}
		}
	}

	@Test
	void selectsPrimaryAndIndependentSecondaryLayoutsForEveryBindingShape() {
		IndexConfiguration configuration = LmdbPageCardinalityEstimator
				.createIndexConfiguration(INDEX_PERMUTATIONS);
		for (int bindingMask = 0; bindingMask < 16; bindingMask++) {
			int expectedPrimary = expectedPrimaryIndex(bindingMask);
			assertEquals(expectedPrimary, configuration.primaryIndex(bindingMask),
					"primary for binding mask " + Integer.toBinaryString(bindingMask));
			assertEquals(expectedSecondaryIndex(expectedPrimary, bindingMask),
					configuration.secondaryIndex(bindingMask),
					"secondary for binding mask " + Integer.toBinaryString(bindingMask));
		}
	}

	@Test
	void rejectsMalformedIndexConfigurations() {
		assertThrows(IllegalArgumentException.class,
				() -> LmdbPageCardinalityEstimator.createIndexConfiguration(List.of()));
		assertThrows(IllegalArgumentException.class,
				() -> LmdbPageCardinalityEstimator.createIndexConfiguration(List.of("spo")));
		assertThrows(IllegalArgumentException.class,
				() -> LmdbPageCardinalityEstimator.createIndexConfiguration(List.of("sppc")));
		assertThrows(IllegalArgumentException.class,
				() -> LmdbPageCardinalityEstimator.createIndexConfiguration(List.of("spox")));
	}

	private static int expectedPrimaryIndex(int bindingMask) {
		int bestIndex = -1;
		int bestPrefixLength = -1;
		int bestResidualScore = Integer.MIN_VALUE;
		for (int index = 0; index < INDEX_PERMUTATIONS.size(); index++) {
			String fieldSequence = INDEX_PERMUTATIONS.get(index);
			int prefixLength = expectedPrefixLength(fieldSequence, bindingMask);
			int residualScore = expectedResidualScore(fieldSequence, bindingMask);
			if (prefixLength > bestPrefixLength
					|| prefixLength == bestPrefixLength && residualScore > bestResidualScore) {
				bestIndex = index;
				bestPrefixLength = prefixLength;
				bestResidualScore = residualScore;
			}
		}
		return bestIndex;
	}

	private static int expectedSecondaryIndex(int primaryIndex, int bindingMask) {
		String primary = INDEX_PERMUTATIONS.get(primaryIndex);
		if (bindingMask == 0 || expectedPrefixLength(primary, bindingMask) != 0) {
			return -1;
		}

		int bestIndex = -1;
		boolean bestHasDifferentLeadingField = false;
		int bestScore = Integer.MIN_VALUE;
		for (int index = 0; index < INDEX_PERMUTATIONS.size(); index++) {
			String candidate = INDEX_PERMUTATIONS.get(index);
			if (index == primaryIndex || expectedPrefixLength(candidate, bindingMask) != 0) {
				continue;
			}
			boolean differentLeadingField = candidate.charAt(0) != primary.charAt(0);
			int score = expectedResidualScore(candidate, bindingMask);
			if (bestIndex == -1 || differentLeadingField && !bestHasDifferentLeadingField
					|| differentLeadingField == bestHasDifferentLeadingField && score > bestScore) {
				bestIndex = index;
				bestHasDifferentLeadingField = differentLeadingField;
				bestScore = score;
			}
		}
		return bestIndex;
	}

	private static int expectedPrefixLength(String fieldSequence, int bindingMask) {
		int prefixLength = 0;
		while (prefixLength < fieldSequence.length()
				&& (bindingMask & componentBit(fieldSequence.charAt(prefixLength))) != 0) {
			prefixLength++;
		}
		return prefixLength;
	}

	private static int expectedPrefixMask(String fieldSequence, int prefixLength) {
		int prefixMask = 0;
		for (int position = 0; position < prefixLength; position++) {
			prefixMask |= componentBit(fieldSequence.charAt(position));
		}
		return prefixMask;
	}

	private static int expectedResidualScore(String fieldSequence, int bindingMask) {
		int score = 0;
		for (int position = 0; position < fieldSequence.length(); position++) {
			if ((bindingMask & componentBit(fieldSequence.charAt(position))) != 0) {
				score += 1 << ((fieldSequence.length() - position - 1) * 4);
			}
		}
		return score;
	}

	private static long expectedRangeValue(int prefixMask, int component) {
		return (prefixMask & (1 << component)) == 0 ? -1L : VALUES[component];
	}

	private static int componentBit(char field) {
		return switch (field) {
		case 's' -> 1;
		case 'p' -> 1 << 1;
		case 'o' -> 1 << 2;
		case 'c' -> 1 << 3;
		default -> throw new IllegalArgumentException("Invalid field: " + field);
		};
	}

	private static List<String> indexPermutations() {
		List<String> permutations = new ArrayList<>();
		addPermutations("", "spoc", permutations);
		return List.copyOf(permutations);
	}

	private static void addPermutations(String prefix, String remaining, List<String> permutations) {
		if (remaining.isEmpty()) {
			permutations.add(prefix);
			return;
		}
		for (int index = 0; index < remaining.length(); index++) {
			addPermutations(prefix + remaining.charAt(index),
					remaining.substring(0, index) + remaining.substring(index + 1), permutations);
		}
	}
}
